-- ---------------------------------------------------------------------------
insert into public.scam_categories (slug, name, description, icon, sort_order) values
  ('phishing',        'Phishing',          'Fake messages that trick you into giving passwords, codes or money.', 'fish', 1),
  ('online-shopping', 'Online Shopping',   'Fake shops, fake sellers and goods that never arrive.', 'cart', 2),
  ('job-scams',       'Job & Income Scams', 'Too-good-to-be-true jobs, paid tasks and "earn from home" tricks.', 'briefcase', 3),
  ('tech-support',    'Tech Support',      'Fake helpers who say your device is infected and ask for money.', 'wrench', 4),
  ('prize-lottery',   'Prize & Lottery',   '"You won!" messages that ask you to pay first.', 'gift', 5),
  ('romance',         'Romance & Friendship', 'Fake friends or partners who build trust then ask for money.', 'heart', 6),
  ('investment-crypto','Investment & Crypto','Fake trading platforms and "guaranteed profit" promises.', 'chart', 7),
  ('impersonation',   'Impersonation',     'Scammers pretending to be police, banks or companies you trust.', 'mask', 8),
  ('malware',         'Malware & Fake Apps','Harmful apps and downloads that steal your data.', 'bug', 9),
  ('identity-theft',  'Identity Theft',    'Stealing your personal details to open accounts or commit fraud.', 'fingerprint', 10)
on conflict (slug) do nothing;

-- ---------------------------------------------------------------------------
-- Scam articles (trusted/official sources; verified)
-- ---------------------------------------------------------------------------
insert into public.scam_articles
  (category_id, title, slug, description, warning_signs, prevention, response_steps,
   reporting_guidance, source_name, source_url, country, trust_level, last_verified, status)
select c.id, v.title, v.slug, v.description, v.warning_signs, v.prevention, v.response_steps,
       v.reporting_guidance, v.source_name, v.source_url, v.country, v.trust_level,
       '2026-08-01'::timestamptz, 'active'
from (values
  ('phishing',
   'Spotting Phishing Messages', 'spotting-phishing-messages',
   'Phishing is when a scammer sends a fake message that looks like it is from a real company, to steal your password, code or money.',
   'Urgency ("act now!"), spelling mistakes, unknown links, asks for your password or one-time code, sender address that is slightly different from the real one.',
   'Never click links in unexpected messages. Type the website address yourself. Turn on two-factor authentication (2FA). Use a password manager.',
   'Do not click or reply. If you clicked, change your password and log out of all devices. If you shared a code, tell a trusted adult and contact the real company.',
   'Report phishing emails and texts to the official reporting organisation for your country (see reporting resources).',
   'APWG & FTC guidance', 'https://www.ftc.gov/news-events/topics/identity-theft/phishing', 'US', 'trusted_official'),
  ('online-shopping',
   'Fake Online Shops', 'fake-online-shops',
   'Scammers build realistic-looking shops with huge discounts, then take your money and send nothing.',
   'Prices far below normal, payment only by bank transfer or gift cards, no contact phone number, the shop was created days ago, reviews all look copied.',
   'Check the domain name, search "<shop name> scam" before buying, pay with a credit card or a payment service that protects buyers.',
   'Keep screenshots of everything, tell a trusted adult, report the payment to your bank, and report the shop to the official reporting organisation.',
   'Report the scam shop so others do not lose money too.',
   'FTC & Action Fraud guidance', 'https://www.actionfraud.police.uk/', 'GB', 'trusted_official'),
  ('job-scams',
   'Job and Task Scams', 'job-task-scams',
   'Fake "jobs" ask you to pay a fee first, share ID documents, or complete paid tasks that later demand your own money.',
   'Interview by chat only, salary far above normal, asks for payment or gift cards to "unlock" the job, asks for ID photos, tasks that pay you to like/rate things.',
   'Real employers never ask for money or gift cards. Never send ID documents to strangers. Talk to a trusted adult before sharing anything.',
   'Stop all contact, keep evidence, do not pay any "fee", report to the official reporting organisation and tell your parent or guardian.',
   'Report the account and the messages so the scam can be taken down.',
   'FTC job scam guidance', 'https://consumer.ftc.gov/articles/job-scams', 'US', 'trusted_official'),
  ('tech-support',
   'Fake Tech Support', 'fake-tech-support',
   'Pop-ups, calls or messages claim your device is infected and demand money to "fix" it.',
   'Sudden pop-up warnings with a phone number, caller claims to be from Microsoft or your bank, asks for remote access to your computer, wants payment in gift cards.',
   'Real companies never call you about viruses. Never give remote access to anyone you did not contact yourself. Close the pop-up (do not call the number).',
   'Tell a trusted adult, disconnect the device from the internet if you are worried, and do not pay anything.',
   'Report the call or pop-up to the official reporting organisation.',
   'FTC tech support guidance', 'https://consumer.ftc.gov/articles/tech-support-scams', 'US', 'trusted_official'),
  ('prize-lottery',
   'Prize and Lottery Scams', 'prize-lottery-scams',
   '"Congratulations, you won!" messages ask you to pay a small fee or share details to receive a prize that does not exist.',
   'You never entered the contest, you must pay to receive the prize, they ask for gift cards or bank details, the message comes from a personal account.',
   'Real prizes are never given to people who did not enter, and winners never pay fees. Ignore and delete the message.',
   'Do not send money or codes. Keep the message as evidence and tell a trusted adult.',
   'Report the message to the official reporting organisation.',
   'FTC prize scam guidance', 'https://consumer.ftc.gov/articles/prizes-sweepstakes-and-lotteries', 'US', 'trusted_official'),
  ('romance',
   'Friendship and Romance Scams', 'friendship-romance-scams',
   'Someone builds a fast online relationship, then finds a reason to ask you for money or gift cards.',
   'Refuses video calls, very fast "I love you", always has an emergency that needs money, asks you to keep it secret, wants gift cards or crypto.',
   'Never send money or gift cards to someone you have only met online. Talk to a trusted adult — real friends never ask you to keep money a secret.',
   'Stop contact, save the chat history, tell a trusted adult, and report the profile.',
   'Report the profile and messages to the platform and the official reporting organisation.',
   'FTC romance scam guidance', 'https://consumer.ftc.gov/articles/romance-scams', 'US', 'trusted_official'),
  ('investment-crypto',
   'Investment and Crypto Scams', 'investment-crypto-scams',
   'Fake trading apps show huge "profits" to convince you to deposit real money that you can never withdraw.',
   'Guaranteed profits, you must pay to withdraw, the app is not on official app stores, famous people "endorsing" it, group chats pressuring you to invest fast.',
   'There is no such thing as a guaranteed profit. Never invest money you cannot afford to lose. Check the platform against official lists of authorised firms.',
   'Do not deposit more. Screenshot everything and tell a trusted adult. Report to the official reporting organisation and the platform.',
   'Report the app or account so it can be taken down.',
   'Action Fraud investment guidance', 'https://www.actionfraud.police.uk/', 'GB', 'trusted_official'),
  ('impersonation',
   'Scammers Pretending to Be the Police or Your Bank', 'impersonation-scams',
   'Callers or messages pretend to be police, banks or government agencies and demand money, codes or personal details.',
   'Demands to act fast, asks for one-time codes or passwords, wants payment by gift cards or crypto, threatens arrest, caller ID can be faked so do not trust it.',
   'Police and banks never ask for your password or one-time code, and never ask for gift card payment. Hang up and call the real organisation using their official number.',
   'If you shared a code, tell a trusted adult immediately and contact the real bank or agency. Keep evidence and report it.',
   'Report the call to the official reporting organisation.',
   'FBI & FTC impersonation guidance', 'https://www.ic3.gov/', 'US', 'trusted_official'),
  ('malware',
   'Fake Apps and Malicious Downloads', 'fake-apps-malware',
   'Harmful apps and downloads that look legit can steal passwords, photos and personal data from your device.',
   'The app is not on the official store, asks for strange permissions (access to messages, photos), battery drains fast, lots of ads, other apps crash.',
   'Only install apps from official stores. Check the developer name and review count. Read the permission list before installing.',
   'Remove the app, run a security scan if you can, change important passwords, and tell a trusted adult.',
   'Report the app to the store and the official reporting organisation.',
   'APWG guidance', 'https://apwg.org/', 'US', 'trusted_official'),
  ('identity-theft',
   'Protecting Your Identity Online', 'protecting-your-identity',
   'Identity theft happens when someone uses your name, date of birth or photos to open accounts or commit fraud.',
   'Accounts you never opened, strange messages from platforms you never joined, someone using your photos, unexpected bills or charges.',
   'Share as little personal information as possible. Use different passwords for every account. Turn on 2FA. Never post photos of IDs or tickets online.',
   'Tell a trusted adult immediately, keep evidence, change passwords, and report to the official reporting organisation for your country.',
   'Report identity theft to the official reporting organisation.',
   'FTC identity theft guidance', 'https://www.identitytheft.gov/', 'US', 'trusted_official')
) as v(category_slug, title, slug, description, warning_signs, prevention, response_steps,
        reporting_guidance, source_name, source_url, country, trust_level)
join public.scam_categories c on c.slug = v.category_slug
on conflict (slug) do nothing;

