-- ---------------------------------------------------------------------------
-- RAG knowledge chunks (trusted guidance only)
-- ---------------------------------------------------------------------------
insert into public.document_chunks (title, content, source_type, trust_level) values
  ('Your account was hacked — what to do now',
   'If your account is hacked: 1) change the password immediately and log out of all devices, 2) turn on two-factor authentication, 3) check recovery email and phone, 4) tell a trusted adult, 5) report to the platform support and to the official reporting organisation for your country.',
   'knowledge', 'trusted_official'),
  ('You shared a one-time code (OTP)',
   'If you sent a one-time code to someone by mistake: that code is a key to your account. Tell a trusted adult right away, log out of all devices, change your password, and check for new devices on your account. Contact the real company through its official support channel.',
   'knowledge', 'trusted_official'),
  ('Strong passwords and passphrases',
   'Use a passphrase: 3 or 4 random words joined together, at least 12 characters. Use a different password for every account. A password manager can create and remember them for you. Never share passwords, even with friends.',
   'knowledge', 'trusted_internal'),
  ('Two-factor authentication (2FA)',
   '2FA adds a second step after your password, like a code from an app, a security key, or biometrics. Turn it on for email, social media, gaming and bank apps. Prefer authenticator apps over SMS codes when the app supports them.',
   'knowledge', 'trusted_internal'),
  ('Red flags in a phishing message',
   'A message is suspicious if it creates urgency, asks for a password or code, uses a wrong sender address, contains odd links, or asks you to pay with gift cards. When in doubt, type the official website yourself instead of clicking the link.',
   'knowledge', 'trusted_official'),
  ('Safe public Wi-Fi use',
   'Public Wi-Fi can be intercepted. Avoid logging into important accounts on open networks; use your mobile data or a trusted VPN instead. Make sure websites show https and never enter passwords on unfamiliar login pages.',
   'knowledge', 'trusted_internal'),
  ('If money was lost to a scam',
   'If you or your family lost money to a scam: tell a trusted adult immediately, contact the bank or payment provider, keep all evidence (screenshots, receipts), and report to the official reporting organisation for your country. Do not pay any more money to the scammer.',
   'knowledge', 'trusted_official'),
  ('Malware on your device',
   'If you suspect malware: stop using the device for important accounts, run a reputable security scan, remove suspicious apps, change passwords from a different device, and tell a trusted adult.',
   'knowledge', 'trusted_internal'),
  ('Personal information that should stay private',
   'Never share passwords, one-time codes, ID documents, bank cards, home addresses or school details with strangers online. Scammers can combine small pieces of information to steal your identity.',
   'knowledge', 'trusted_official'),
  ('Reporting scams to official organisations',
   'MATRIX AI never invents reporting websites. Reporting guidance always comes from the verified reporting resources database, which contains official organisations such as the FTC, Action Fraud, Scamwatch and the Canadian Anti-Fraud Centre.',
   'knowledge', 'trusted_internal')
on conflict (id) do nothing;

