  ('phishing-scam-detection', 'Common Scam Families', 'Shopping, jobs, prizes, tech support and more.', 2),
  ('phishing-scam-detection', 'How to Check and Report', 'Verifying messages and reporting scams.', 3),
  ('password-mfa-security', 'Passwords That Work', 'Passphrases and password managers.', 1),
  ('password-mfa-security', 'Two-Factor Authentication', 'The second lock on your accounts.', 2),
