  ('privacy-digital-footprint', 'Data Brokers and Trackers', 'Who collects your data and why.', 2),
  ('privacy-digital-footprint', 'Privacy on Every Device', 'Browser, phone and app privacy habits.', 3),
  ('device-security', 'Keeping Devices Updated', 'Updates, locks and screen time hygiene.', 1),
  ('device-security', 'Safe Downloads and Apps', 'Where apps come from and what permissions mean.', 2),
