-- Lessons: (course, module, title, body, sort)
insert into public.lessons (module_id, title, body, sort_order)
select m.id, v.title, v.body, v.sort
from (values
  -- Cyber Safety Basics
  ('cyber-safety-basics','Your Online Accounts','Your email is the master key to everything you do online.',
   'Your email address is usually the "master key": if someone takes over your email, they can reset passwords for your other accounts. That is why your email password should be the strongest one you have, and why you should never share it — even with your closest friends. Turn on two-factor authentication for email first, before any other account. If an account is important, it deserves a unique password. Use your school or personal email carefully: never use it to sign up for random websites, because those sites can be hacked or sold.', 1),
  ('cyber-safety-basics','How Accounts Get Taken Over','Most account takeovers are not genius hacks — they are leaked passwords and shared codes.',
   'Most account takeovers happen because of leaked passwords (a website you used got hacked), reused passwords (same password everywhere), or shared one-time codes. A scammer does not need to "hack" you if you hand them the key. Watch for signs an account is compromised: messages sent that you did not write, password reset emails you did not request, or a "logged in from a new device" alert you did not cause. If you see these signs, act calmly: change the password, log out of all devices, and tell a trusted adult.', 2),
  ('cyber-safety-basics','Messages from People You Do Not Know','Strangers online can pretend to be anyone — including your friends.',
   'Scammers fake messages from friends, companies and even police. A friend asking for a code or money in a strange way? Call them or ask in person. A company asking for your password? Real companies never do that. Before replying to an unexpected message, ask: did I expect this? Does it push me to act fast? Does it ask for a secret? If yes to any of these, do not reply — and never click links in messages you did not expect.', 1),
  ('cyber-safety-basics','The Pause Rule','Slowing down defeats most scams, because scams run on speed.',
   'Scams work by rushing you: "act now", "your account will close", "you won but must pay today". The Pause Rule is simple: when a message makes you feel rushed, stop. Do not click, do not reply, do not send money or codes. Take ten minutes. Check with a trusted adult. Type the official website yourself instead of clicking the link. Almost every scam collapses when you slow down.', 2),
  ('cyber-safety-basics','If Something Goes Wrong','Bad things happen — the right response fixes most of the damage.',
   'If you clicked a suspicious link, shared a code, or lost money: you are not in trouble, and the fastest way to limit damage is to act quickly and calmly. Tell a trusted adult immediately. Change the affected passwords from a different device. Log out of all sessions. Keep screenshots as evidence. Use the Emergency help ("I Need Help Now") section for step-by-step guidance specific to what happened. The worst thing you can do is hide it or wait.', 1),
  ('cyber-safety-basics','Getting Help Without Judgment','MATRIX AI is a judgment-free space — and so should your reporting experience be.',
   'Everyone makes mistakes online; that is how we learn. The platform never blames you, and neither should you blame yourself. You can ask the AI anything about cybersecurity, use Emergency mode for step-by-step help, or report a scam to the official reporting organisation. If you are being pressured, threatened or blackmailed online, that is never your fault — tell a trusted adult or a support service right away.', 2),
  -- Phishing & Scam Detection
  ('phishing-scam-detection','Anatomy of a Phishing Message','Every phishing message has a small set of ingredients.',
   'Phishing messages usually contain: an urgent demand, a fake sender address (like amaz0n-support@mail.ru), a link to a lookalike login page, and a request for a secret (password, code, card number). The message may be an email, SMS, WhatsApp, or a chat in a game. Look at the language: real companies do not send "Dear customer, your account will be deleted in 24 hours" emails. When a message asks for a secret, it is a scam, full stop.', 1),
  ('phishing-scam-detection','Spotting Lookalike Links','Scammers hide fake addresses behind friendly text.',
   'The text of a link can say anything — "click here" — while the real address goes somewhere else. Hover over (or long-press) a link to preview the true address before clicking. Look for misspellings of real brands (paypa1, faceb00k) and unusual endings (.xyz, .top, .shop). In messages from friends, the address is still the thing to check. When in doubt, do not click: open a new tab and type the official site yourself.', 2),
  ('phishing-scam-detection','Fake Shops and Fake Goods','Too-good-to-be-true prices are the main ingredient of shopping scams.',
   'Fake shops copy real store designs, use stolen logos, and offer huge discounts. They usually only accept bank transfers or gift cards, which leave no protection. Before buying: check the domain age and spelling, search "<shop name> + scam", look for a real phone number and physical address, and pay with buyer-protected methods. If a deal looks impossible, it is a scam — walk away.', 1),
  ('phishing-scam-detection','Job, Prize and Tech-Support Traps','Three scam families that target teens specifically.',
   'Job scams offer easy money for "tasks" then demand fees or ID photos. Prize scams say you won something you never entered and ask for a "fee" to release it. Tech-support scams pop up with virus warnings and ask you to call a number or pay to "fix" your device. Real jobs do not charge you, real prizes do not ask for money, and real tech companies never call you about viruses. If it costs money to receive money, it is a scam.', 2),
  ('phishing-scam-detection','Verifying a Suspicious Message','A simple checklist turns suspicion into certainty.',
   'When a message feels off, run the checklist: 1) Who really sent it? (check the raw address, not the display name). 2) Did I expect this? 3) Does it create urgency? 4) Does it ask for a secret or money? 5) Is the link address correct? If two or more checkboxes are ticked, treat it as a scam: do not reply, do not click, report it. You can also paste the message into the MATRIX AI chat for a safe analysis.', 1),
  ('phishing-scam-detection','Reporting a Scam','Reporting protects you and everyone else.',
   'Reporting a scam takes two minutes and helps platforms and authorities take it down. Save evidence first: screenshots of the message, the sender address, and the link (without clicking it). Then report through the platform (most apps have a report button), and report to the official reporting organisation for your country using the verified reporting resources in this app. MATRIX AI never invents reporting websites — it always uses verified official contacts.', 2),
  -- Password & MFA
  ('password-mfa-security','Passphrases Beat Passwords','Length beats complexity when it comes to passwords.',
   'A passphrase is 3–4 random words put together, like "purple-lantern-cloud-42". It is long, easy for you to remember, and hard for computers to guess. Avoid personal details (your name, birthday, pet) because scammers can find those online. Never reuse passwords: when one site leaks your password, scammers try it on every other site. That is how most accounts get taken over.', 1),
  ('password-mfa-security','Password Managers','Let software create and remember unique passwords for you.',
   'A password manager is an app that generates strong random passwords and stores them in one encrypted vault protected by one master passphrase. You only need to remember the master passphrase. Use one on your phone and computer, turn on its auto-lock, and never share the vault. If you are under 18, ask a trusted adult to help you set it up — it is one of the highest-impact security upgrades available.', 2),
  ('password-mfa-security','What 2FA Is and Why It Matters','A second lock stops stolen passwords from being enough.',
   'Two-factor authentication (2FA) means that logging in needs your password plus a second proof: a code from an authenticator app, a hardware security key, or your fingerprint/face. If a scammer steals your password but not your phone, they still cannot get in. Turn on 2FA for email, social media, gaming and bank apps. Prefer authenticator apps (like Google Authenticator or Authy) over SMS codes when possible.', 1),
  ('password-mfa-security','Setting Up 2FA the Right Way','The setup moment is when most 2FA mistakes happen.',
   'When you enable 2FA, save the recovery codes somewhere safe — a printed note or a password manager — because if you lose your phone, those codes are your only way back in. Never screenshot recovery codes into your photo gallery where other apps can read them. After setup, test it: log out and log back in. If a message asks for your 2FA code, remember: the code is only for the login screen you opened yourself — anyone who asks for it by message is a scammer.', 2),
  ('password-mfa-security','Recovery Options','Recovery email and phone are the emergency exits of your account.',
   'Every important account lets you add recovery options: a backup email or a phone number. Keep them up to date — an old recovery email is how accounts get lost forever. Beware of "account recovery" scams that claim to be support and ask for codes or money to restore an account. Real recovery is free and never asks for your password. If you lose access, use the official recovery flow on the real website only.', 1),
  ('password-mfa-security','Auditing Your Passwords','A yearly password check-up is a healthy habit.',
   'Once a year (or after any scare), do a password audit: list your important accounts, check that each has a unique strong password and 2FA, remove old unused accounts (they can be hacked and forgotten), and update recovery email/phone. Security check-up tools from password managers can show you which passwords were leaked in data breaches — change those first.', 2),
  -- Social Media Security
  ('social-media-security','Reading Privacy Settings','Privacy settings are a choose-your-own-adventure — pick the right one.',
   'On every social platform, go through settings and decide: who can see your posts (friends only beats public), who can message you, who can find you by phone/email, and whether your profile appears in search engines. Check the settings on each app you use — they are all different. Review them again after app updates, because defaults can change. A private profile is not paranoid; it is normal.', 1),
  ('social-media-security','What to Never Post','Some things should never go online, even to friends.',
   'Never post: your exact home address, school address, ID documents or tickets (QR codes can be scanned), bank card photos, passwords or codes, or photos that show your location in real time. Even "private" posts can be screenshotted by someone you trusted. Think of everything you post as potentially public forever. A good rule: if you would not show it on a big screen at school, do not post it.', 2),
  ('social-media-security','Handling Stranger Requests','Strangers use kindness, compliments and gifts to earn trust.',
   'Not every stranger online is a scammer — but the ones who are use the same playbook: flattery, secrets ("this is our private thing"), gifts, and slowly asking for personal details, photos or money. If someone you have never met in person asks for money, gift cards, private photos, or to keep your chats secret — that is a massive red flag. Tell a trusted adult. You never owe a stranger anything, online or offline.', 1),
  ('social-media-security','Location and Live Features','Sharing where you are, live, is sharing your schedule.',
   'Location tags on posts tell people where you are now; live features tell people where you are right now. Turn off precise location for social apps, post places after you have left them, and avoid live-streaming from home. Photos taken with a phone carry hidden location data — platforms may strip it, but not always. Check each app\'s location settings and set them to "never" or "while using".', 2),
  ('social-media-security','What Cyberbullying Looks Like','Bullying online is still bullying — and it is not your fault.',
   'Cyberbullying includes repeated mean messages, spreading rumours, fake accounts impersonating you, sharing your private photos, and excluding or threatening you. It often happens where adults cannot see it. If it is happening to you: do not respond to the bully (that feeds the fire), save evidence (screenshots with dates), block the accounts, and tell a trusted adult or a school counsellor. Most platforms have anti-bullying reporting tools; use them.', 1),
  ('social-media-security','Blocking, Muting and Reporting','The block button is a health tool, not a punishment.',
   'You are allowed to block anyone, any time, for any reason — you do not owe anyone access to you. Learn the platform\'s flow: block the account, report harassment with evidence, and tell a trusted adult if it escalates. If a bully switches accounts, keep reporting and keep evidence. In many countries, severe cyberbullying and threats are illegal — reporting to the official reporting organisation is an option, especially if you feel unsafe.', 2),
  -- Privacy & Digital Footprint
  ('privacy-digital-footprint','Your Digital Footprint','Everything you do online leaves a trail that lasts.',
   'Your digital footprint is the trail of everything you post, search, like, buy and share — plus what others post about you. It is built from social posts, gaming profiles, school projects, comments, and even old accounts you forgot. Once something is online, it can be copied, archived and screenshotted. Before posting, ask: would I be okay seeing this on a screen in ten years? Because it might be there.', 1),
  ('privacy-digital-footprint','The Footprint Audit','Find out what the internet knows about you.',
   'A footprint audit: 1) search your name in a search engine and note what comes up, 2) list every account you ever made, 3) delete the ones you do not use, 4) tighten privacy settings on the rest, 5) remove old posts that reveal too much. Do this with a trusted adult the first time. Deleting old accounts is one of the best privacy moves a teenager can make.', 2),
  ('privacy-digital-footprint','Who Collects Your Data','Free apps are not free — data is the payment.',
   'Many free apps and websites make money from your data: your interests, location, friends and habits are collected, combined and sold to advertisers and data brokers. This is why you see eerily relevant ads. Check app permissions, use "ask every time" for location, reject unnecessary tracking cookies, and use privacy-friendly browsers. Reading what data an app collects is a real skill — start with the app store\'s data-safety labels.', 1),
  ('privacy-digital-footprint','Trackers and Cookies','Cookies can be harmless or creepy — know the difference.',
   'Cookies are small files websites use to remember you. Some are needed to stay logged in; others track you across sites to build an advertising profile. Most browsers let you block third-party cookies and clear history. Use private/incognito windows for sensitive research, and consider privacy-focused search engines. When a site asks for cookie consent, "reject non-essential" is a perfectly good choice.', 2),
  ('privacy-digital-footprint','Privacy on Your Phone','Your phone knows where you are, what you say, and who you talk to.',
   'Phone privacy starts with the lock screen (PIN or biometric), then app permissions: review which apps have camera, microphone, contacts, and location access, and revoke the ones that do not need it. Turn off personalised ads where the OS lets you, check app-by-app location settings, and be careful installing "flashlight" apps that want your contacts — they have no reason to need them.', 1),
  ('privacy-digital-footprint','Sharing with Care','Oversharing is a habit; sharing with care is a skill.',
   'Before sharing personal information, ask: who needs this, why do they need it, and what could go wrong if it leaked? Legitimate sites rarely need your full name, birthdate, address and phone at once. Use nicknames where real names are not required, avoid birthdate fields where possible, and be wary of quizzes and "personality tests" that harvest data — they are often data-collection traps. Sharing less is always an option, and it is always okay.', 2),
  -- Device Security
  ('device-security','Updates Are Security','That annoying update popup is actually a security patch.',
   'Updates fix security holes that attackers know about — the moment a fix is released, attackers race to break the unfixed versions. Turn on automatic updates for your phone, laptop, apps and browser. Restart devices regularly so updates can finish. If a device is too old to update anymore, stop using it for important accounts like banking and email; old devices are the easiest targets.', 1),
  ('device-security','Locks and Screen Hygiene','The physical lock is the first line of defence.',
   'A phone or laptop without a lock is an open door: anyone who picks it up has your accounts, photos and messages. Set a strong PIN or biometric lock, enable auto-lock after a short time, and never share your unlock code — even with friends (they might lose the device, or the code can be screenshotted). Lock your screen when you walk away, even at home. Log out of shared computers when you are done.', 2),
  ('device-security','Where Apps Come From','Official app stores are the safe door; everywhere else is a gamble.',
   'Install apps only from official stores (Google Play, App Store, Microsoft Store) and check the developer name, download counts and reviews. "Sideloading" apps from random websites or links in messages is how most mobile malware spreads. Before installing, read the permission list: a game does not need your contacts, a wallpaper app does not need your camera. When an app asks for a strange permission, that is the moment to say no.', 1),
  ('device-security','Spotting Fake Apps','Fake apps borrow real names and icons to trick you.',
   'Fake apps appear in search results and ads with slightly wrong names (WhatsApp+), copied icons, and a handful of downloads. Clues: very few downloads, recent creation date, broken grammar, or demands for payment before use. Check the developer name against the official one. If an app asks for accessibility permissions or device-admin rights, that is a serious red flag — those powers can read your screen.', 2),
  ('device-security','Backups','A backup is your safety net against loss, breakage and ransomware.',
   'Backups mean your photos and files are not lost if a device breaks, is stolen, or is locked by malware. Enable automatic backup to a cloud account you control (with 2FA on that account!), or back up to an external drive. Test a restore once in a while. For important school work, keep copies in two places. A backup you have never tested is a hope, not a plan.', 1),
  ('device-security','Selling, Recycling and Wiping','Wipe before you let a device go.',
   'Before selling, trading or recycling a device: back up what you need, then do a factory reset (and for computers, a full disk wipe if possible). Log out of every account first, and remove SIM/memory cards. A factory reset is not optional — the next owner should never see your photos, messages or saved passwords. Also remove your account from the device so it cannot be remotely accessed later.', 2),
  -- Cybersecurity Fundamentals
  ('cybersecurity-fundamentals','Social Engineering','The easiest way past any security is a human.',
   'Social engineering is manipulating people into giving away access — the "hacker" is usually a conversation, not code. Phishing, fake phone calls, impersonation and urgent requests are all social engineering. Defenders train themselves to notice when a request asks for something unusual, creates pressure, or plays on fear, greed or helpfulness. The human firewall — knowing when to say no — is the most important control in any system, including your own accounts.', 1),
  ('cybersecurity-fundamentals','Malware Families','Malware is not one thing — it is a family of threats.',
   'Common malware families: viruses (attach to files), worms (spread by themselves), Trojans (hide inside useful-looking software), ransomware (locks your files and demands payment), spyware (watches you silently), and adware (floods ads). Key idea: most malware needs a human to let it in — a fake download, a malicious link, or a USB stick. Updates, safe downloads and suspicious-link habits block most of the family at the door.', 2),
  ('cybersecurity-fundamentals','Exploits and Vulnerabilities','A vulnerability is a bug with a price tag.',
   'A vulnerability is a flaw in software that attackers can abuse; an exploit is the attack that uses it. That is why updates matter: patches close known vulnerabilities. In cybersecurity, people who find vulnerabilities can report them responsibly (responsible disclosure) instead of exploiting them — companies often reward this through bug bounty programs. Learning how vulnerabilities are found and fixed is a core defender skill.', 1),
  ('cybersecurity-fundamentals','Defence in Depth','Layered defence means no single failure is fatal.',
   'Defence in depth means several independent layers: strong unique passwords, 2FA, updated software, cautious clicking, backups, and limited sharing. If one layer fails (say, a password leaks), the next one (2FA) still holds. Security is not one perfect action; it is many imperfect ones stacked. The same idea applies to your accounts: recovery options, alerts and regular check-ups are layers too.', 2),
  ('cybersecurity-fundamentals','What Ethical Hacking Is','Hacking skills are like fire — useful or destructive depending on how you use them.',
   'Ethical hacking (white hat) is using hacking skills to find and fix weaknesses with permission. Bug bounty platforms let researchers test companies\' systems legally and get paid for findings. The line is permission: testing a system you do not own, or without authorisation, is illegal and harmful. Never "test" your school, someone else\'s account, or any system without written permission. The skills that make a great defender are the same skills that make a dangerous attacker — choose the defender path.', 1),
  ('cybersecurity-fundamentals','Your Path in Cybersecurity','From learner to white hat: a realistic roadmap.',
   'If you love this stuff, the path is: build strong fundamentals (networking, Linux, programming), learn on legal sandboxes (TryHackMe, HackTheBox, picoCTF), earn beginner certifications when old enough, join CTF (capture the flag) competitions, and eventually pursue responsible disclosure or bug bounty programs. School subjects that help: maths, computer science, and English (for writing clear security reports). Never break the law to "prove" skills — the white hat community will not respect it, and the law will not ignore it.', 2)
) as v(course_slug, module_title, title, body, sort)
join public.course_modules m on m.title = v.module_title
join public.courses c on c.id = m.course_id and c.slug = v.course_slug
on conflict (module_id, sort_order) do nothing;

-- Quizzes: one per module
insert into public.quizzes (module_id, title, pass_percent, sort_order)
select m.id, 'Quiz: ' || m.title, 60, 1
from public.course_modules m
on conflict (module_id, sort_order) do nothing;

